// Emerald Rupture documentation site. Data: docs/data/*.json, generated by tools/gen5/site_export.py in the game repo.
(function () {
  "use strict";
  const $ = (s, el) => (el || document).querySelector(s);
  const esc = s => String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const TYPES = { Normal: "#9a9a6e", Fire: "#e5642c", Water: "#4f7fe0", Electric: "#d8b324", Grass: "#5fa83f", Ice: "#6cc2c2", Fighting: "#b22d26",
    Poison: "#94409a", Ground: "#cfa652", Flying: "#8f7ee0", Psychic: "#e8507a", Bug: "#93a221", Rock: "#a8913a", Ghost: "#6a5590",
    Dragon: "#6a3cf0", Dark: "#6a5446", Steel: "#9a9ab8", Fairy: "#d97fa0" };
  const type = t => t ? `<span class="type" style="background:${TYPES[t] || "#555"}">${esc(t)}</span>` : "";
  // same file names the calc uses for its sprites
  const slug = n => n.toLowerCase().replace(" ", "-").replace(".", "").replace(".", "").replace("’", "").replace(":", "-");
  // fallbacks for forms the sprite set lacks (new Megas, Toxtricity-Amped...): no apostrophe, then the base species
  const spriteTries = n => { const a = slug(n), b = a.replace(/'/g, ""), c = b.split("-")[0]; return [...new Set([a, b, c])]; };
  window.rdocsSprite = img => {
    const t = (img.dataset.t || "").split("|"); const i = +(img.dataset.i || 0) + 1;
    if (i < t.length) { img.dataset.i = i; img.src = `../img/pokesprite/${encodeURIComponent(t[i])}.png`; } else img.style.visibility = "hidden";
  };
  const sprite = (n, cls) => { const t = spriteTries(n);
    return `<img loading="lazy" ${cls ? `class="${cls}"` : ""} data-t="${esc(t.join("|"))}" src="../img/pokesprite/${encodeURIComponent(t[0])}.png" alt="" onerror="rdocsSprite(this)">`; };
  const store = { get(k, d) { try { const v = localStorage.getItem("rdocs." + k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
                  set(k, v) { try { localStorage.setItem("rdocs." + k, JSON.stringify(v)); } catch (e) {} } };
  const cache = {};
  const load = f => cache[f] || (cache[f] = fetch("data/" + f).then(r => { if (!r.ok) throw new Error(f + ": " + r.status); return r.json(); }));

  const S = { dir: store.get("dir", "forward"), diff: store.get("diff", "normal"), dbl: store.get("dbl", false), bosses: store.get("bosses", false),
    boss: store.get("boss", 0), sel: store.get("sel", null), tab: store.get("tab", "main"), rival: store.get("rival", "Cheren"),
    starter: store.get("starter", "Tadbulb"), show: store.get("show", "all"), boxes: store.get("boxes", false) };
  let page = "trainers", rendered = null;

  function seg(key, opts, label) {
    return `<span class="seg" title="${label}">` + opts.map(([v, t]) => `<button data-k="${key}" data-v="${v}" class="${String(S[key]) === String(v) ? "on" : ""}">${t}</button>`).join("") + "</span>";
  }
  function options() {
    const o = $("#opts");
    if (page === "prep") {
      o.innerHTML = seg("dir", [["forward", "Forward"], ["rewind", "Rewind"]], "Bosses direction") + seg("diff", [["normal", "Normal"], ["hard", "Hard"]], "Difficulty");
      o.querySelectorAll("button").forEach(b => b.onclick = () => { S[b.dataset.k] = b.dataset.v; store.set(b.dataset.k, b.dataset.v); options(); show(); });
      return;
    }
    if (page !== "trainers") { o.innerHTML = ""; return; }
    o.innerHTML = seg("dir", [["forward", "Forward"], ["rewind", "Rewind"]], "Bosses direction") +
      seg("diff", [["normal", "Normal"], ["hard", "Hard"]], "Difficulty") +
      seg("dbl", [[false, "Singles"], [true, "Doubles"]], "Battle mode") +
      `<label class="chk"><input type="checkbox" id="bossonly" ${S.bosses ? "checked" : ""}> Bosses only</label>`;
    o.querySelectorAll("button").forEach(b => b.onclick = () => {
      let v = b.dataset.v; if (v === "true") v = true; if (v === "false") v = false;
      S[b.dataset.k] = v; store.set(b.dataset.k, v); options(); show();
    });
    $("#bossonly").onchange = e => { S.bosses = e.target.checked; store.set("bosses", S.bosses); filter(); };
  }

  // ---------------------------------------------------------------- trainers
  function calcFile() { return "rupture" + (S.dir === "rewind" ? "-rewind" : "") + (S.diff === "hard" ? "-hard" : ""); }
  function calcLink(id) {
    return `../index.html?data=${calcFile()}&gen=8&dmgGen=8&types=6&customPoks=1&noSwitch=1&evs=0&opp=${encodeURIComponent(id)}`;
  }
  function monCard(m) {
    const moves = (m.m || []).map(x => `<li>${esc(x)}</li>`).join("");
    return `<div class="mon">${sprite(m.s)}<div class="nm">${esc(m.s)} <span class="sub">Lv ${m.l}</span></div>
      <div class="sub">${esc(m.a)}${m.n ? " · " + esc(m.n) : ""}</div><div class="sub">${m.i ? "@ " + esc(m.i) : "&nbsp;"}</div>
      <ul>${moves}</ul><a class="calc" href="${calcLink(m.c)}" target="_blank" rel="noopener">Calc ↗</a></div>`;
  }
  async function trainers() {
    const base = `trainers-${S.dir}-${S.diff}`;
    const [single, doubles] = await Promise.all([load(base + ".json"), S.dbl ? load(base + "-doubles.json") : Promise.resolve([])]);
    const dmap = {}; doubles.forEach(t => dmap[t.id] = t);
    let html = `<p class="intro">Every trainer in the order you meet them, with exact levels, abilities, natures, held items and moves.
      <b>${S.dir === "rewind" ? "Rewind" : "Forward"}</b> bosses, <b>${S.diff === "hard" ? "Hard" : "Normal"}</b>, <b>${S.dbl ? "Doubles mode" : "single battles"}</b>.
      Easy isn't listed separately: it uses the Normal teams a few levels lower, with simpler AI. Calc opens the damage calculator with that Pokémon loaded; use its Read .sav button to bring in your own team.</p>`;
    let lastLoc = null, lastPh = null;
    single.forEach((t0, i) => {
      const t = dmap[t0.id] ? Object.assign({}, t0, { team: dmap[t0.id].team, dteam: true }) : t0;
      if (t.ph !== lastPh) { html += `<h2 class="ph">${esc(t.ph)}</h2>`; lastPh = t.ph; lastLoc = null; }
      if (t.loc !== lastLoc) { html += `<h3 class="sec" data-loc="${esc(t.loc)}">${esc(t.loc)}</h3>`; lastLoc = t.loc; }
      const text = [t.t, t.loc, t.cls].concat(t.team.map(m => m.s)).join(" ").toLowerCase();
      html += `<section class="tr ${t.boss ? "boss" : ""}" data-boss="${t.boss ? 1 : 0}" data-text="${esc(text)}" data-loc="${esc(t.loc)}">
        <div class="tr-h"><b>${esc(t.t)}</b>${t.boss ? '<span class="tag boss">Boss</span>' : ""}
        ${t.dbl || t.dteam ? `<span class="tag dbl">${t.dteam ? "Doubles team" : "Double battle"}</span>` : ""}
        ${t.items ? `<span class="tag it">${esc(t.items)}</span>` : ""}</div>
        <div class="team">${t.team.map(monCard).join("")}</div></section>`;
    });
    return html;
  }

  // ---------------------------------------------------------------- pokedex
  async function pokedex() {
    const dex = await load("pokedex.json");
    const head = "<tr><th></th><th>#</th><th>Pokémon</th><th>Type</th><th>Abilities</th><th>HP</th><th>Atk</th><th>Def</th><th>SpA</th><th>SpD</th><th>Spe</th><th>Total</th></tr>";
    const rows = dex.map((d, i) => `<tr class="row" data-i="${i}" data-text="${esc([d.name, d.types.join(" "), d.ab.join(" "), d.ha].join(" ").toLowerCase())}">
      <td>${sprite(d.c)}</td><td class="n">${d.no}</td><td><b>${esc(d.name)}</b></td><td>${d.types.map(type).join("")}</td>
      <td>${esc(d.ab.join(" / "))}${d.ha ? `<br><span class="muted">HA: ${esc(d.ha)}</span>` : ""}</td>
      ${d.bs.map(v => `<td class="n">${v}</td>`).join("")}<td class="n"><b>${d.tot}</b></td></tr>`).join("");
    return `<p class="intro">The regional Pokédex (${dex.length} entries with forms and Megas). Tap a Pokémon for its evolution, where to find it and its moves.</p>
      <div class="wrap dex"><table><thead>${head}</thead><tbody>${rows}</tbody></table></div>`;
  }
  function dexDetail(tr) {
    const next = tr.nextElementSibling;
    if (next && next.classList.contains("det")) { next.remove(); return; }
    load("pokedex.json").then(dex => {
      const d = dex[+tr.dataset.i];
      const lvl = d.lvl.map(([l, m]) => `<span class="chip">${l === 0 ? "Evo" : "Lv " + l} ${esc(m)}</span>`).join("");
      const tm = d.tm.map(m => `<span class="chip">${esc(m)}</span>`).join("");
      tr.insertAdjacentHTML("afterend", `<tr class="det"><td colspan="12"><div class="cols">
        <div><b>Evolution</b><br>${esc(d.evo || "Does not evolve")}<br><br><b>Where to find it</b><br>${esc(d.where || "Not found in the wild (see Encounters for gifts)")}</div>
        <div><b>Level-up moves</b><br>${lvl || "—"}</div><div><b>TM / tutor moves</b><br>${tm || "—"}</div></div></td></tr>`);
    });
  }

  // ---------------------------------------------------------------- simple tables
  function table(cols, rows, intro) {
    const num = rows.length ? rows[0].cells.map(c => !!(c && c.n)) : [];
    return (intro ? `<p class="intro">${intro}</p>` : "") + `<div class="wrap"><table><thead><tr>${cols.map((c, i) => `<th${num[i] ? ' class="n"' : ""}>${c}</th>`).join("")}</tr></thead><tbody>` +
      rows.map(r => `<tr data-text="${esc(r.text.toLowerCase())}" ${r.cls ? `class="${r.cls}"` : ""}>${r.cells.map(c => `<td${c.n ? ' class="n"' : ""}>${c.h != null ? c.h : esc(c)}</td>`).join("")}</tr>`).join("") +
      "</tbody></table></div>";
  }
  async function moves() {
    const mv = await load("moves.json");
    return table(["Move", "Type", "Category", "Power", "Acc", "PP", "Prio", "TM", "Tutor", "Effect"],
      mv.map(m => ({ text: [m.name, m.type, m.cat, m.eff].join(" "), cells: [{ h: `<b>${esc(m.name)}</b>` }, { h: type(m.type) }, m.cat,
        { h: esc(m.pow || "—"), n: 1 }, { h: esc(m.acc || "—"), n: 1 }, { h: esc(m.pp), n: 1 }, { h: esc(m.pri || ""), n: 1 }, m.tm || "", m.tutor || "", m.eff] })),
      "Every move a Pokémon in this game can learn.");
  }
  let CN = null;   // Pokedex display name -> calc name (sprites)
  async function calcNames() {
    if (!CN) { CN = {}; (await load("pokedex.json")).forEach(d => CN[d.name] = d.c); }
    return CN;
  }
  const spr = (n, cls) => sprite((CN && CN[n]) || n, cls);
  async function encounters() {
    await calcNames();
    const e = await load("encounters.json");
    let html = `<p class="intro">Wild encounters, grouped by Nuzlocke area (one catch per area). Green = grass, brown = cave or Rock Smash, blue = water or fishing. Chance is that species' share of the method on that map.</p>`;
    e.areas.forEach(a => {
      html += `<h3 class="sec" data-loc="${esc(a.area)}">${esc(a.area)} <span class="muted">${a.nuz ? "· Nuzlocke area " + a.nuz : "· not a Nuzlocke area"}</span></h3>`;
      html += table(["", "Map", "Method", "Pokémon", "Level", "Chance", "Notes"], a.rows.map(r => ({
        text: [a.area, r.map, r.how, r.s, r.note].join(" "), cls: { grass: "g", cave: "c", water: "w", fish: "w", surf: "w" }[r.kind] || (/(surf|rod|fish)/i.test(r.how) ? "w" : ""),
        cells: [{ h: spr(r.s.split(" (")[0], "") }, r.map, r.how, { h: `<b>${esc(r.s)}</b>` }, { h: esc(r.lv), n: 1 }, { h: esc(r.pct) + (typeof r.pct === "number" ? "%" : ""), n: 1 }, r.note] })));
    });
    html += `<h3 class="sec">Gifts, trades, fossils and other Pokémon</h3>` + table(["Where", "How", "Pokémon", "Level", "Notes"],
      e.other.map(o => ({ text: [o.where, o.how, o.s, o.note].join(" "), cells: [o.where, o.how, { h: `<b>${esc(o.s)}</b>` }, { h: esc(o.lv), n: 1 }, o.note || ""] })));
    return html;
  }
  async function tms() {
    const t = await load("tms.json");
    return table(["TM/HM", "Move", "Where"], t.map(x => ({ text: [x.no, x.move, x.where.join(" ")].join(" "),
      cells: [{ h: `<b>${esc(x.no)}</b>` }, x.move, x.where.join(", ") || "Shops / gym leaders"] })), "Every TM and HM and where to get it. TMs can be used again and again.");
  }
  async function items() {
    const it = await load("items.json");
    return table(["Item", "Where and how", "How to get more"], it.items.map(x => ({ text: [x.name, x.where, x.more].join(" "),
      cells: [{ h: `<b>${esc(x.name)}</b>` }, x.where, x.more || ""] })), "Every item you can find, be given or buy.") +
      `<h3 class="sec">Shops</h3>` + table(["Shop", "Stock", "Added", "Removed"], it.shops.map(x => ({ text: [x.shop, x.stock].join(" "),
        cells: [{ h: `<b>${esc(x.shop)}</b>` }, x.stock, x.added || "", x.removed || ""] })));
  }
  async function abilities() {
    const a = await load("abilities.json");
    return table(["Ability", "Pokémon"], a.map(x => ({ text: [x.name].concat(x.mons).join(" "), cells: [{ h: `<b>${esc(x.name)}</b>` }, x.mons.join(", ")] })),
      "Which Pokémon in the regional dex can have each ability.");
  }
  async function changes() {
    await calcNames();
    const i = await load("info.json");
    let html = `<h3 class="sec">Changelog</h3>` + table(["Version", "Change"], i.changelog.map(c => ({ text: c.v + " " + c.t, cells: [{ h: `<b>${esc(c.v)}</b>` }, c.t] })));
    html += `<h3 class="sec">After the Elite Four</h3>` + table(["What", "Where", "How"], i.postgame.map(p => p.what.startsWith("§")
      ? { text: p.what, cells: [{ h: `<b>${esc(p.what.slice(2))}</b>` }, "", ""] } : { text: [p.what, p.where, p.how].join(" "), cells: [p.what, p.where, p.how] }));
    html += `<h3 class="sec">Features</h3>` + table(["Area", "What"], i.features.map(f => ({ text: f.a + " " + f.t, cells: [{ h: `<b>${esc(f.a)}</b>` }, f.t] })));
    html += `<h3 class="sec">Legendary and mythical Pokémon</h3>` + table(["Pokémon", "Level", "Where", "How"], i.legends.map(l => ({ text: [l.s, l.where, l.how].join(" "),
      cells: [{ h: spr(l.s) + " <b>" + esc(l.s) + "</b>" }, { h: esc(l.lv), n: 1 }, l.where, l.how] })));
    html += `<h3 class="sec">Evolution changes</h3>` + table(["Pokémon", "Official games", "This game"], i.evos.map(e => ({ text: [e.s, e.was, e.now].join(" "), cells: [{ h: `<b>${esc(e.s)}</b>` }, e.was, e.now] })));
    return html;
  }

  // ---------------------------------------------------------------- boss prep
  // Data: prep-<dir>-<diff>.json from tools/gen5/balance_check.py --site. Each matchup cell:
  // [you win 1-on-1, your best move, its min %, max %, their best move, its min %, max %, you move first]
  let MINE = new Set(store.get("mine", []));
  // prep-<dir>-<diff>.json: {pools: {"stage|cap": [Pokémon]}, bosses: [{..., pk, pool: [{i, m, top}]}]}
  const PREP = {};
  async function loadPrep() {
    const f = `prep-${S.dir}-${S.diff}.json`;
    if (!PREP[f]) {
      const d = await load(f);
      PREP[f] = d.bosses.map(e => Object.assign({}, e, { pool: e.pool.map(x => Object.assign({}, d.pools[e.pk][x.i], x)) }))
        .sort((a, b) => a.ord - b.ord);
    }
    return PREP[f];
  }
  const TABS = [["main", "Gyms & League"], ["villain", "Villains"], ["rival", "Rivals & required trainers"], ["all", "Everything, in story order"]];
  const inTab = e => S.tab === "all" || (S.tab === "main" ? e.group === "gym" : e.group === S.tab);
  const keyOf = e => e.vgroup ? "vg:" + e.vgroup : e.id;
  function pickVariant(list) {
    return list.find(e => e.vrival === S.rival && e.vstarter === S.starter) || list.find(e => e.vstarter === S.starter) || list[0];
  }
  function buttons(all) {   // one per fight; Cheren/Bianca's six versions share one
    const seen = new Set(), out = [];
    all.filter(inTab).forEach(e => { const k = keyOf(e); if (!seen.has(k)) { seen.add(k); out.push(e); } });
    return out;
  }
  function resolve(all, key) {
    const list = key && key.startsWith("vg:") ? all.filter(e => keyOf(e) === key) : all.filter(e => e.id === key);
    return list.length ? (list[0].vgroup ? pickVariant(list) : list[0]) : null;
  }
  const beaten = e => !!(SAVE && SAVE.info.defeated && SAVE.info.defeated.includes(e.n));
  function storyLabel(x) {
    if (x.group === "gym") return BOSS_SHORT(x);
    if (x.vgroup) return x.vgroup.replace("Cheren/Bianca · ", "Cheren/Bianca · ").split(" (")[0];
    const name = x.t.replace(/^(Rival|Elite Trainer) /, "").split(/[,(]/)[0].trim(), fight = (x.t.match(/fight (\d)/) || [])[1];
    return fight ? `${name} ${fight}` : `${name} · ${x.loc.split(/[,(]/)[0].trim()}`;
  }
  const BOSS_SHORT = x => { const nm = x.t.replace(/^(Gym \d: |Leader |Elite Four:? |Champion )/, "").split(/[ (,]/)[0];
    return (x.stage.startsWith("Gym") ? x.stage : /Champion/.test(x.t) ? "Champion" : "E4") + " · " + nm; };
  function prepCalc(e, r, j) {
    const own = [r.m[j][1]].concat(r.top || []).filter((m, i, a) => m && a.indexOf(m) === i).slice(0, 4);
    return calcLink(e.team[j].c) + `&me=${encodeURIComponent(CN[r.s] || r.s)}&lv=${e.cap}&mv=${encodeURIComponent(own.join(","))}`;
  }
  // ---- your save (read in the browser; nothing is uploaded) and the same 1-on-1 model as the data files
  let SAVE = store.get("save", null), META = null, CUR = null;
  const KEYS = ["hp", "at", "df", "sa", "sd", "sp"], IVKEYS = ["hp", "at", "df", "sp", "sa", "sd"];   // the reader's IV order
  function statsOf(bs, lv, ivs, evs, nature) {
    const up = (META.natures[nature] || [])[0], down = (META.natures[nature] || [])[1], st = {};
    KEYS.forEach((k, i) => {
      const iv = ivs[k], ev = Math.floor((evs[k] || 0) / 4), b = bs[i];
      st[k] = k === "hp" ? Math.floor((2 * b + iv + ev) * lv / 100) + lv + 10
        : Math.floor((Math.floor((2 * b + iv + ev) * lv / 100) + 5) * (k === up ? 1.1 : k === down ? 0.9 : 1));
    });
    return st;
  }
  function makeMon(name, lv, opt) {
    const d = META.mons[name];
    if (!d) return null;
    const ivs = {}, evs = {};
    IVKEYS.forEach((k, i) => { ivs[k] = opt.ivs ? opt.ivs[i] : opt.iv; evs[k] = opt.evs ? opt.evs[i] : 0; });
    return { name, lv, t: d.t, ab: opt.ab || d.ab, item: opt.item || "", moves: opt.moves || [], st: statsOf(d.bs, lv, ivs, evs, opt.nature || "Hardy") };
  }
  const eff = (mt, types) => types.reduce((x, t) => x * ((META.chart[mt] || {})[t] ?? 1), 1);
  function damage(att, dfn, move, intim) {
    const m = META.moves[move];
    if (!m) return 0;
    let [mt, cat, bp] = m;
    if (META.fixed[move] != null) return eff(mt, dfn.t) === 0 ? 0 : (META.fixed[move] === "level" ? att.lv : META.fixed[move]);
    if (!bp || cat === "Status") return 0;
    const phys = cat === "Physical";
    let a = att.st[phys ? "at" : "sa"]; const d = dfn.st[phys ? "df" : "sd"];
    if (phys && (att.ab === "Huge Power" || att.ab === "Pure Power")) a *= 2;
    if (phys && intim) a = Math.floor(a * 2 / 3);
    if (att.ab === "Technician" && bp <= 60) bp *= 1.5;
    const base = Math.floor(Math.floor(Math.floor(2 * att.lv / 5 + 2) * bp * a / d) / 50) + 2;
    const stab = att.t.includes(mt) ? (att.ab === "Adaptability" ? 2 : 1.5) : 1;
    const item = META.boost[att.item] === mt ? 1.2 : att.item === "Life Orb" ? 1.3 : ((att.item === "Choice Band" && phys) || (att.item === "Choice Specs" && !phys)) ? 1.5 : 1;
    let e = eff(mt, dfn.t);
    if (META.immune[dfn.ab] === mt) e = 0;
    if (dfn.ab === "Thick Fat" && (mt === "Fire" || mt === "Ice")) e *= 0.5;
    return base * 0.925 * stab * e * item * (META.multi[move] || 1);
  }
  // like Python's max() over (damage, move): ties go to the later name
  const best = (a, d, intim) => a.moves.reduce((b, m) => { const x = damage(a, d, m, intim); return !b[1] || x > b[0] || (x === b[0] && m > b[1]) ? [x, m] : b; }, [0, null]);
  function matchup(p, b) {   // same rule as tools/gen5/balance_check.py: KO it before it KOs you
    const [pd, pm] = best(p, b, b.ab === "Intimidate"), [bd, bm] = best(b, p, p.ab === "Intimidate");
    const first = p.st.sp >= b.st.sp;
    let win = false;
    if (pd > 0) { const ph = Math.ceil(b.st.hp / pd), bh = bd > 0 ? Math.ceil(p.st.hp / bd) : 99; win = first ? ph <= bh : ph < bh; }
    const pc = x => { const f = Math.floor(x), r = x - f; return r > 0.5 ? f + 1 : r < 0.5 ? f : (f % 2 ? f + 1 : f); };   // Python's round()
    return [win ? 1 : 0, pm || "", pc(pd / b.st.hp * 100 * .85 / .925), pc(pd / b.st.hp * 100 / .925), bm || "",
            pc(bd / p.st.hp * 100 * .85 / .925), pc(bd / p.st.hp * 100 / .925), first ? 1 : 0];
  }
  const bossMon = m => makeMon(m.s, m.l, { iv: 31, nature: m.n, ab: m.a, item: m.i, moves: m.m });
  const saveMon = m => makeMon(m.name, m.level, { ivs: m.ivs, evs: m.evs, nature: m.nature, ab: m.ability, item: m.item, moves: m.moves });
  function ownedNat() {
    const out = new Set();
    if (SAVE) SAVE.party.concat(...SAVE.boxes).forEach(m => { const d = META.mons[m.name]; if (d && d.nat) out.add(d.nat); });
    return out;
  }
  function famOf(name) { const d = META && META.mons[name]; return d && d.fam ? d.fam : []; }
  function nextBoss(info) {
    if (info.nBadges < 8) return info.nBadges;
    if (info.gameClear) return 12;
    return 8 + info.e4.reduce((a, b) => a + b, 0);
  }
  const DIFF = { normal: "Normal", hard: "Hard", easy: "Easy" };
  function saveBar(e) {
    if (!SAVE) return `<div class="savebar"><label class="savebtn">Read your save (.sav)<input type="file" id="prepsave" accept=".sav,.srm,.sa1,.dsv,.fla,application/octet-stream"></label>
      <span class="muted">Loads your party, PC boxes, badges, mode and (in a Nuzlocke) the areas you've used, and jumps to your next boss. The file stays on your device.</span></div>`;
    const i = SAVE.info, nz = i.nuzlocke ? ` · Nuzlocke: ${i.areasUsed.length} of ${META.areas} areas used${i.areasExact ? "" : "*"}` : "";
    return `<div class="savebar on"><b>${esc(i.name || "Your save")}</b><span>${i.rewind ? "Rewind" : "Forward"} · ${DIFF[i.difficulty]}${i.doubles ? " · Doubles" : ""} · ${i.nBadges} badge${i.nBadges === 1 ? "" : "s"}${nz}</span>
      <span class="muted">${SAVE.party.length} in party, ${SAVE.total - SAVE.party.length} in the PC · read ${esc(SAVE.when || "")}</span>
      <label class="savebtn small">Read again<input type="file" id="prepsave" accept=".sav,.srm,.sa1,.dsv,.fla,application/octet-stream"></label><button class="savebtn small" id="prepforget">Forget</button>
      ${i.difficulty === "easy" ? `<span class="note">Easy uses the Normal teams a few levels lower; Normal is shown.</span>` : ""}
      ${i.doubles ? `<span class="note">Doubles mode: bosses use their Doubles teams (see Trainers → Doubles); this page shows the singles teams.</span>` : ""}
      ${i.nuzlocke && !i.areasExact ? `<span class="note">* A 2.9 save: the area list can include a few areas that a picked-up item marked. Continue it once in 2.9.1 and save to make it exact.</span>` : ""}</div>`;
  }
  async function readSaveFile(file) {
    const buf = await file.arrayBuffer();
    const res = window.readRuptureSave(buf, true);
    const d = new Date();
    SAVE = { info: res.info, party: res.party, boxes: res.boxes, total: res.total, when: d.toLocaleDateString() + " " + d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) };
    store.set("save", SAVE);
    S.dir = res.info.rewind ? "rewind" : "forward"; store.set("dir", S.dir);
    S.diff = res.info.difficulty === "hard" ? "hard" : "normal"; store.set("diff", S.diff);
    S.rival = res.info.gender ? "Cheren" : "Bianca"; store.set("rival", S.rival);   // a boy faces Bianca, a girl Cheren
    const st = ["Tadbulb", "Tandemaus", "Fidough"].find(n => META && famOf(n).some(x => res.info.caught.includes(x)));
    if (st) { S.starter = st; store.set("starter", S.starter); }
    S.sel = null; store.set("sel", null);   // the page picks your next fight
  }

  const isMine = r => r.from.some(f => MINE.has(f)) || (SAVE && famOf(r.s).some(n => OWNED.has(n)));
  let OWNED = new Set();
  function nuzStatus(r) {   // in a Nuzlocke save: can you still catch this one?
    if (!SAVE || !SAVE.info.nuzlocke) return null;
    if (famOf(r.s).some(n => SAVE.info.caught.includes(n))) return ["dupe", "Dupe (family caught)"];
    if (!r.areas.length) return ["gift", "Gift / starter"];
    const free = r.areas.filter(([a, nz]) => !nz || !SAVE.info.areasUsed.includes(nz));
    return free.length ? ["free", "Catch: " + free.map(x => x[0]).join(", ")] : ["used", "Areas used"];
  }
  async function prep() {
    await calcNames();
    const [all, meta] = await Promise.all([loadPrep(), load("prep-meta.json")]);
    META = meta; OWNED = ownedNat();
    const btns = buttons(all);
    let e = S.sel && btns.some(b => keyOf(b) === S.sel) ? resolve(all, S.sel) : null;
    if (!e) {   // first fight in this tab you haven't won yet (with a save), else the first one
      const b = (SAVE && btns.find(x => !(x.vgroup ? all.filter(y => keyOf(y) === keyOf(x)).some(beaten) : beaten(x)))) || btns[0];
      e = resolve(all, keyOf(b));
    }
    CUR = e;
    const n = e.pool.length, team = e.team;
    let html = `<p class="intro">Pick the next boss, or read your save. This page lists every Pokémon you could have by then (caught in the areas you can reach, evolved by level up to the cap, with its level-up moves and the TMs you can have by then) and works out who wins each 1-on-1 at the level cap. Tap ☆ on Pokémon you've caught, or read your save, to see how your team lines up.</p>
      ${saveBar(e)}<div class="prepf tabs">` + TABS.map(([k, t]) => `<button data-tab="${k}" class="${S.tab === k ? "on" : ""}">${t}</button>`).join("") + `</div>
      <div class="bosspick">` + btns.map(x => { const k = keyOf(x), won = x.vgroup ? all.filter(y => keyOf(y) === k).some(beaten) : beaten(x);
        return `<button data-k="${esc(k)}" class="${k === keyOf(e) ? "on" : ""} ${won ? "done" : ""} g-${x.group}" title="${esc(x.t + " · " + x.loc)}">${won ? "✓ " : ""}${esc(storyLabel(x))}</button>`; }).join("") + `</div>`;
    if (e.vgroup) html += `<p class="prepf">Rival: ${["Cheren", "Bianca"].map(v => `<button data-rival="${v}" class="${e.vrival === v ? "on" : ""}">${v}${v === "Cheren" ? " (you're a girl)" : " (you're a boy)"}</button>`).join("")}
      &nbsp; Your starter: ${["Tadbulb", "Tandemaus", "Fidough"].map(v => `<button data-starter="${v}" class="${e.vstarter === v ? "on" : ""}">${v}</button>`).join("")}</p>`;
    html += `<div class="prephead"><b>${esc(e.t)}</b> <span class="muted">${esc(e.loc)} · level cap ${e.cap} · ${n} Pokémon you could have</span>
      ${e.items_used ? `<span class="tag it">${esc(e.items_used)}</span>` : ""}${e.dbl || /multi battle/.test(e.loc) ? `<span class="tag dbl">${/multi battle/.test(e.loc) ? "Multi battle" : "Double battle"}: matchups below are still 1-on-1</span>` : ""}
      ${e.group !== "gym" ? `<span class="muted">· your level cap here is the next gym's</span>` : ""}</div>`;
    // boss team with how many of your options beat each
    html += `<div class="team">` + team.map((m, j) => {
      const k = e.pool.filter(r => r.m[j][0]).length, pct = Math.round(k / n * 100);
      return monCard(m).replace('<a class="calc"', `<div class="beat"><div class="barw"><div class="fill ${pct < 20 ? "lo" : pct < 40 ? "mid" : ""}" style="width:${pct}%"></div></div>
        <span>${k} of ${n} beat it</span></div><a class="calc"`);
    }).join("") + `</div>`;
    // your actual Pokémon from the save
    if (SAVE) {
      const bosses = team.map(bossMon);
      const list = SAVE.party.concat(S.boxes ? [].concat(...SAVE.boxes) : []);
      html += `<h3 class="sec">Your Pokémon vs ${esc(storyLabel(e))} (from your save)</h3>
        <p class="prepf"><label class="chk"><input type="checkbox" id="prepboxes" ${S.boxes ? "checked" : ""}> Include the PC boxes</label>
        <span class="muted">Your real levels, natures, IVs, abilities, items and moves. ✓ = wins 1-on-1.</span></p>`;
      html += `<div class="wrap"><table class="prep mine"><thead><tr><th>Pokémon</th><th class="n">Wins</th>` +
        team.map(m => `<th class="bm">${spr(m.s)}<br>${esc(m.s)} ${m.l}</th>`).join("") + `</tr></thead><tbody>`;
      const covered = team.map(() => false);
      list.forEach((m, k) => {
        const p = saveMon(m);
        if (!p) return;
        const cells = bosses.map(b => b ? matchup(p, b) : null), wins = cells.filter(c => c && c[0]).length;
        cells.forEach((c, j) => { if (c && c[0] && k < SAVE.party.length) covered[j] = true; });
        const over = !SAVE.info.capsOff && m.level > e.cap;
        html += `<tr data-text="${esc([m.name, m.ability, m.item].concat(m.moves).join(" ").toLowerCase())}"><td class="pk">${spr(m.name)}<div><b>${esc(m.name)}</b> <span class="muted">Lv ${m.level}</span>
          ${k < SAVE.party.length ? '<span class="tag boss">Party</span>' : '<span class="tag">PC</span>'}${over ? `<span class="tag over">Over the cap (${e.cap})</span>` : ""}
          <br><span class="muted">${esc(m.nature)} · ${esc(m.ability)}${m.item ? " · @ " + esc(m.item) : ""}</span><br><span class="muted">${esc(m.moves.join(", "))}</span></div></td>
          <td class="n"><b>${wins}</b>/${team.length}</td>` + cells.map((c, j) => !c ? "<td></td>" :
          `<td class="mu ${c[0] ? "w" : "l"}"><a href="${calcLink(team[j].c)}&me=${encodeURIComponent(m.name)}&lv=${m.level}&mv=${encodeURIComponent(m.moves.join(","))}" target="_blank" rel="noopener" title="Open in the calc">${c[0] ? "✓" : "✗"}</a>
          <span>${esc(c[1] || "—")} ${c[1] ? c[2] + "–" + c[3] + "%" : ""}</span><span class="muted">takes ${c[4] ? c[5] + "–" + c[6] + "%" : "nothing"}${c[7] ? "" : " · slower"}</span></td>`).join("") + `</tr>`;
      });
      html += `</tbody></table></div>`;
      const gaps = team.filter((m, j) => !covered[j]);
      if (gaps.length) html += `<p class="note">Nothing in your party wins 1-on-1 against ${gaps.map(m => "<b>" + esc(m.s) + "</b>").join(", ")}. The list below shows what you could catch or use for ${gaps.length === 1 ? "it" : "them"}.</p>`;
    }
    // your team (stars)
    const mine = e.pool.filter(isMine);
    html += `<h3 class="sec">${SAVE ? "Your species at their best" : "Your team"} vs ${esc(storyLabel(e))}</h3>`;
    if (SAVE) html += `<p class="muted">Each species you own (★), as it would be at the level cap with the moves it can have by now.</p>`;
    if (!mine.length) html += `<p class="muted">Tap ☆ next to Pokémon you've caught (in the list below). Your picks are remembered on this device and carry over to every boss, evolved to what they'd be by then.</p>`;
    else html += `<div class="cover">` + team.map((m, j) => {
      const w = mine.filter(r => r.m[j][0]);
      return `<div class="cv ${w.length ? "" : "gap"}">${spr(m.s)}<div><b>${esc(m.s)}</b> <span class="muted">Lv ${m.l}</span><br>${w.length
        ? w.map(r => `<a href="${prepCalc(e, r, j)}" target="_blank" rel="noopener">${esc(r.s)}</a> <span class="muted">(${esc(r.m[j][1])})</span>`).join(", ")
        : "<span class='bad'>Nothing on your team wins this 1-on-1</span>" + (() => { const alt = e.pool.filter(r => r.m[j][0] && !isMine(r)).slice(0, 3);
          return alt.length ? `<br><span class="muted">Options: ${alt.map(r => esc(r.s) + " (" + esc(r.where[0] || "") + ")").join(", ")}</span>` : ""; })()}</div></div>`;
    }).join("") + `</div>`;
    // matchup table
    html += `<h3 class="sec">Every Pokémon you could have</h3>
      <p class="prepf">${[["all", "All"], ["mine", "Only mine"], ["new", "New since the last boss"]].concat(SAVE && SAVE.info.nuzlocke ? [["free", "Catchable now"]] : []).map(([v, t]) =>
        `<button data-show="${v}" class="${S.show === v ? "on" : ""}">${t}</button>`).join("")}
      <span class="muted">✓ = wins 1-on-1. Each cell: your best move and its damage, then their best hit on you. Tap a row for details.</span></p>`;
    html += `<div class="wrap"><table class="prep"><thead><tr><th></th><th>Pokémon</th><th class="n">Wins</th>` +
      team.map(m => `<th class="bm">${spr(m.s)}<br>${esc(m.s)} ${m.l}</th>`).join("") + `</tr></thead><tbody>`;
    e.pool.forEach((r, i) => {
      const wins = r.m.reduce((a, c) => a + c[0], 0), mineR = isMine(r), nz = nuzStatus(r);
      const show = S.show === "all" || (S.show === "mine" && mineR) || (S.show === "new" && r.new) || (S.show === "free" && nz && nz[0] === "free" && !mineR) || (S.show === "free" && !nz);
      if (!show) return;
      html += `<tr class="pr" data-i="${i}" data-text="${esc([r.s].concat(r.from, r.types, r.where).join(" ").toLowerCase())}">
        <td><button class="star ${mineR ? "on" : ""}" data-f="${esc(r.from.join("|"))}" title="I have this">${mineR ? "★" : "☆"}</button></td>
        <td class="pk">${spr(r.s)}<div><b>${esc(r.s)}</b>${r.new ? ' <span class="tag new">New</span>' : ""}${SAVE && famOf(r.s).some(x => OWNED.has(x)) ? ' <span class="tag boss">Yours</span>' : nz ? ` <span class="tag nz-${nz[0]}">${esc(nz[1])}</span>` : ""}<br>${r.types.map(type).join("")}
          <br><span class="muted">${esc(r.from.join(" / ") !== r.s ? "from " + r.from.join(" / ") + " · " : "")}${esc(r.where.join("; "))}</span></div></td>
        <td class="n"><b>${wins}</b>/${team.length}</td>` +
        r.m.map((c, j) => `<td class="mu ${c[0] ? "w" : "l"}"><a href="${prepCalc(e, r, j)}" target="_blank" rel="noopener" title="Open in the calc">${c[0] ? "✓" : "✗"}</a>
          <span>${esc(c[1] || "—")} ${c[1] ? c[2] + "–" + c[3] + "%" : ""}</span><span class="muted">takes ${c[4] ? c[5] + "–" + c[6] + "%" : "nothing"}</span></td>`).join("") + `</tr>`;
    });
    html += `</tbody></table></div>`;
    if (S.show !== "all" && !e.pool.some(r => { const nz = nuzStatus(r), m = isMine(r);
      return (S.show === "mine" && m) || (S.show === "new" && r.new) || (S.show === "free" && (!nz || (nz[0] === "free" && !m))); }))
      html += `<p class="muted">${{ mine: "None of these yet: tap ☆ or read your save.", new: "Nothing new since the last boss.",
        free: "Nothing left to catch before this boss: every area you can reach is used, or the families are already caught." }[S.show] || ""}</p>`;
    // supplies
    if (e.tms.length) html += `<h3 class="sec">TMs you can get since the last boss</h3>` + table(["TM", "Move", "Where"],
      e.tms.map(x => ({ text: [x.no, x.move].concat(x.where).join(" "), cells: [{ h: `<b>${esc(x.no)}</b>` }, x.move, x.where.join(", ")] })));
    if (e.items.length) html += `<h3 class="sec">Items you can find since the last boss</h3>` + table(["Item", "Where"],
      e.items.map(x => ({ text: [x.name].concat(x.where).join(" "), cells: [{ h: `<b>${esc(x.name)}</b>` }, x.where.join("; ")] })));
    html += `<h3 class="sec">How this is worked out</h3><p class="intro">Your Pokémon are at the level cap with average IVs (15), a neutral nature, their first ability, no held item and no stat boosts.
      They can use every level-up move up to the cap, including the Lv 1 moves a wild catch often doesn't know yet: relearn those (and any TM move whose TM is in your bag) for free from the Pokémon's summary screen, on the Moves page, with START.
      Tutor moves count once you've reached the tutor's town (the relearner offers them from then on); egg moves and the Battle Frontier tutors are post-game, so they never count here.
      Each side uses its strongest damaging move every turn (STAB, type matchups, the boss's held item and abilities such as Intimidate, Technician, Levitate and the type-absorbing ones are counted).
      The faster Pokémon hits first; you "win" if you knock it out before it knocks you out. Status moves, setup, switching, crits, accuracy, weather and the AI's choices aren't modelled,
      so treat ✓ as "a good matchup", not a guaranteed win, and check close ones in the calc. Areas reached: ${esc(e.new_areas.join(", "))}.</p>`;
    return html;
  }
  function prepChange(ev) {
    if (ev.target.id === "prepsave" && ev.target.files[0]) {
      readSaveFile(ev.target.files[0]).then(() => { options(); rendered = null; show(); })
        .catch(err => { alert("Couldn't read that save: " + err.message); });
      return true;
    }
    if (ev.target.id === "prepboxes") { S.boxes = ev.target.checked; store.set("boxes", S.boxes); rendered = null; const y = scrollY; show().then(() => scrollTo(0, y)); return true; }
    return false;
  }
  function prepClick(ev) {
    if (ev.target.id === "prepforget") { SAVE = null; store.set("save", null); rendered = null; show(); return true; }
    const st = ev.target.closest(".star");
    if (st) {
      ev.stopPropagation();
      const f = st.dataset.f.split("|"), on = !f.some(x => MINE.has(x));
      f.forEach(x => on ? MINE.add(x) : MINE.delete(x));
      store.set("mine", [...MINE]); rendered = null; const y = scrollY; show().then(() => scrollTo(0, y)); return true;
    }
    const b = ev.target.closest(".bosspick button");
    if (b) { S.sel = b.dataset.k; store.set("sel", S.sel); rendered = null; show(); return true; }
    const tb = ev.target.closest(".tabs button");
    if (tb) { S.tab = tb.dataset.tab; store.set("tab", S.tab); rendered = null; show(); return true; }
    const rv = ev.target.closest("[data-rival]"), sv = ev.target.closest("[data-starter]");
    if (rv || sv) { if (rv) { S.rival = rv.dataset.rival; store.set("rival", S.rival); } else { S.starter = sv.dataset.starter; store.set("starter", S.starter); }
      rendered = null; const y = scrollY; show().then(() => scrollTo(0, y)); return true; }
    const sh = ev.target.closest(".prepf button");
    if (sh) { S.show = sh.dataset.show; store.set("show", S.show); rendered = null; const y = scrollY; show().then(() => scrollTo(0, y)); return true; }
    const tr = ev.target.closest("tr.pr");
    if (tr && !ev.target.closest("a")) { prepDetail(tr); return true; }
    return false;
  }
  function prepDetail(tr) {
    const next = tr.nextElementSibling;
    if (next && next.classList.contains("det")) { next.remove(); return; }
    Promise.resolve(CUR).then(e => {
      const r = e.pool[+tr.dataset.i];
      const lines = e.team.map((m, j) => { const c = r.m[j];
        return `<li><b>${c[0] ? "✓" : "✗"} vs ${esc(m.s)}</b>: ${c[7] ? "you move first" : "it moves first"}. ${c[1] ? `Your ${esc(c[1])} does ${c[2]}–${c[3]}%` : "You have no damaging move that hits it"}${c[4] ? `; its ${esc(c[4])} does ${c[5]}–${c[6]}% to you.` : "; it can't damage you."}
          <a href="${prepCalc(e, r, j)}" target="_blank" rel="noopener">Calc ↗</a></li>`; }).join("");
      tr.insertAdjacentHTML("afterend", `<tr class="det"><td colspan="${3 + e.team.length}"><div class="cols"><div><b>Matchups</b><ul class="ml">${lines}</ul></div>
        <div><b>Moves counted</b> <span class="muted">(${esc(r.ab)}; Lv 1, TM and unlocked tutor moves can be relearned from the summary screen with START)</span><br>${r.moves.map(m => `<span class="chip">${esc(m)}</span>`).join("")}</div></div></td></tr>`);
    });
  }

  // ---------------------------------------------------------------- shell
  const PAGES = { trainers, prep, pokedex, moves, encounters, tms, items, abilities, changes };
  // each location heading and what follows it become one collapsible group
  function groupSections() {
    const main = $("#main");
    main.querySelectorAll("h3.sec").forEach(h => {
      const d = document.createElement("details");
      d.className = "grp";
      d.open = page !== "encounters";
      const sum = document.createElement("summary");
      sum.innerHTML = h.innerHTML;
      d.appendChild(sum);
      let el = h.nextElementSibling;
      while (el && !(el.tagName === "H3" || el.tagName === "H2")) {
        const nx = el.nextElementSibling; d.appendChild(el); el = nx;
      }
      h.replaceWith(d);
    });
    if (main.querySelector("details.grp")) {
      main.insertAdjacentHTML("afterbegin", '<p class="fold"><button data-f="1">Expand all</button> <button data-f="0">Collapse all</button></p>');
      main.querySelectorAll(".fold button").forEach(b => b.onclick = () =>
        main.querySelectorAll("details.grp").forEach(d => { if (d.style.display !== "none") d.open = b.dataset.f === "1"; }));
    }
  }
  function filter() {
    const q = $("#q").value.trim().toLowerCase();
    const main = $("#main");
    main.querySelectorAll("[data-text]").forEach(el => {
      const hide = (q && !el.dataset.text.includes(q)) || (page === "trainers" && S.bosses && el.dataset.boss === "0");
      el.style.display = hide ? "none" : "";
      if (hide && el.nextElementSibling && el.nextElementSibling.classList.contains("det")) el.nextElementSibling.remove();
    });
    // hide groups with nothing visible; open the ones with search matches
    main.querySelectorAll("details.grp").forEach(d => {
      const any = !!d.querySelector("[data-text]:not([style*='none'])") || (!q && !d.querySelector("[data-text]"));
      d.style.display = any ? "" : "none";
      if (q && any) d.open = true;
    });
  }
  async function show() {
    page = (location.hash.slice(1) || "trainers").split("?")[0];
    if (!PAGES[page]) page = "trainers";
    document.querySelectorAll("#nav a").forEach(a => a.classList.toggle("on", a.getAttribute("href") === "#" + page));
    options();
    const key = page + JSON.stringify(S) + (page === "prep" && SAVE ? SAVE.when : "");
    if (rendered === key) return;
    $("#main").innerHTML = '<p class="muted">Loading…</p>';
    try {
      $("#main").innerHTML = await PAGES[page]();
      groupSections();
      rendered = key;
      filter();
    } catch (e) {
      $("#main").innerHTML = `<p>Couldn't load this section (${esc(e.message)}). Check your connection and reload.</p>`;
    }
  }
  $("#main").addEventListener("change", e => { if (page === "prep") prepChange(e); });
  $("#main").addEventListener("click", e => { if (page === "prep" && prepClick(e)) return; const tr = e.target.closest(".dex tr.row"); if (tr) dexDetail(tr); });
  let t; $("#q").addEventListener("input", () => { clearTimeout(t); t = setTimeout(filter, 150); });
  window.addEventListener("hashchange", () => { $("#q").value = ""; show(); });
  load("info.json").then(i => { $("#ver").textContent = i.version; document.title = `Emerald Rupture ${i.version} Docs`; }).catch(() => {});
  show();
})();
